function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const Friendship = [], seen = new Set();
  const add = (x, y) => {
    if (x === y) return;
    const a = Math.min(x, y), b = Math.max(x, y);
    if (seen.has(`${a}|${b}`)) return;
    seen.add(`${a}|${b}`);
    Friendship.push([a, b]);
  };
  if (size === 'small') {
    const limit = pick(9);
    // Often plant a pair with 2 or 3 common friends (sometimes without the pair's own friendship), then fill randomly.
    if (rand() < 0.5) {
      const ids = [1, 2, 3, 4, 5, 6, 7];
      for (let i = ids.length - 1; i > 0; i--) { const j = pick(i + 1); [ids[i], ids[j]] = [ids[j], ids[i]]; }
      if (rand() < 0.8) add(ids[0], ids[1]);
      const commons = 2 + pick(2);
      for (let k = 2; k < 2 + commons; k++) { add(ids[0], ids[k]); add(ids[1], ids[k]); }
    }
    for (let tries = 0; tries < 40 && Friendship.length < limit; tries++) add(1 + pick(7), 1 + pick(7));
    return [{ Friendship }];
  }
  // Large: 30 groups of 8 users; low-numbered groups get many more edges, so density (and strength) varies.
  for (let tries = 0; tries < 8000 && Friendship.length < 2000; tries++) {
    if (rand() < 0.6) {
      const group = Math.floor(30 * rand() * rand());
      add(group * 8 + 1 + pick(8), group * 8 + 1 + pick(8));
    } else add(1 + pick(240), 1 + pick(240));
  }
  return [{ Friendship }];
}
